namespace ghidra.feature.vt.gui.task;




using ghidra.feature.vt.api.main;
using ghidra.feature.vt.api.util;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;

public class RejectMatchTask : VtTask {

	private List<VTMatch> matches;

	public RejectMatchTask(VTSession session, List<VTMatch> matches) : base("Reject Matches", session)
    {
		this.matches = matches;
	}

	/* @Override */
	protected bool doWork(TaskMonitor monitor)
    {
		rejectMatches(monitor);
		return true;
	}

	private void rejectMatches(TaskMonitor monitor)
    {
		monitor.setMessage("Updating status for matches");
		monitor.initialize(matches.size());
		foreach (VTMatch match in matches) {
			monitor.checkCancelled();
			VTAssociation association = match.getAssociation();
			VTAssociationStatus status = association.getStatus();
			if (status == VTAssociationStatus.ACCEPTED || status == VTAssociationStatus.REJECTED) {
				continue;
			}
			try {
				association.setRejected();
			}
			catch (VTAssociationStatusException e) {
				throw new AssertException("Should have been given an association that is not " +
					"blocked - current status: " + association.getStatus());
			}
			monitor.incrementProgress(1);
		}

		monitor.setProgress(matches.size());
	}

//==================================================================================================
// Inner Classes
//==================================================================================================

	private class ErrorStatus {
		private List<Exception> exceptions = new();

		bool hasErrors() {
			return exceptions.size() > 0;
		}
	}
}
